import { getLocationFromIP } from "./metadata";
import { LocationData } from "../types/index.type";

interface BulkRequestOptions {
    batchSize?: number;
    batchDelay?: number;
    requestTimeout?: number;
    maxRetries?: number;
    debug?: boolean;
    autoRetry?: boolean;
    maxAutoRetries?: number;
}

interface BulkResult {
    success: Array<{ ip: string; data: LocationData }>;
    failed: Array<{ ip: string; error: string }>;
    stats: {
        total: number;
        successful: number;
        failed: number;
        duration: number;
        batchesProcessed: number;
    };
}

export class FetchGeolocation {
    private ips = new Set<string>();
    private failedIPs = new Set<string>();
    private isProcessing = false;
    private lastRequestTime = 0;
    private requestCount = 0;
    private readonly RATE_LIMIT_WINDOW = 60000;
    private readonly MAX_REQUESTS_PER_MINUTE = 45;
    private debug = false;
    private currentErrors = new Map<string, string>();

    setDebug(enabled: boolean): void {
        this.debug = enabled;
    }

    private debugLog(message: string): void {
        if (this.debug) console.log(message);
    }

    private debugUpdate(message: string): void {
        if (this.debug) {
            // Truncate message if too long to prevent terminal overflow
            const maxLength = 80;
            const truncated = message.length > maxLength 
                ? message.substring(0, maxLength - 3) + '...' 
                : message;
            process.stdout.write('\r' + truncated);
        }
    }

    private debugComplete(message: string): void {
        if (this.debug) {
            // Clear any existing content on line, then write message
            process.stdout.write('\r' + ' '.repeat(100) + '\r' + message + '\n');
        }
    }

    private debugError(ip: string, error: string, clear = false): void {
        if (!this.debug) return;
        
        if (clear) {
            this.currentErrors.delete(ip);
        } else {
            const currentError = this.currentErrors.get(ip);
            if (currentError === error) return; // Prevent spam
            this.currentErrors.set(ip, error);
        }
        
        // Limit error display to prevent terminal overflow
        if (this.currentErrors.size > 0) {
            const errorEntries = Array.from(this.currentErrors.entries());
            const maxDisplay = 3; // Only show first 3 errors
            
            const displayErrors = errorEntries.slice(0, maxDisplay);
            const remainingCount = errorEntries.length - maxDisplay;
            
            let errorText = displayErrors
                .map(([ip, err]) => `${ip}(${err})`)
                .join(', ');
                
            if (remainingCount > 0) {
                errorText += `, +${remainingCount} more`;
            }
            
            // Clear line and show clean error
            process.stdout.write('\r' + ' '.repeat(100) + '\r'); // Clear line
            this.debugUpdate(`❌ ${errorText}`);
        } else {
            // Clear error line completely
            process.stdout.write('\r' + ' '.repeat(100) + '\r');
        }
    }

    addIPs(ips: string[]): void {
        for (const ip of ips) {
            if (this.isValidIP(ip)) {
                this.ips.add(ip);
                this.failedIPs.delete(ip);
            }
        }
    }

    addIP(ip: string): void {
        if (this.isValidIP(ip)) {
            this.ips.add(ip);
            this.failedIPs.delete(ip);
        }
    }

    getIPs(): string[] {
        return Array.from(this.ips);
    }

    getFailedIPs(): string[] {
        return Array.from(this.failedIPs);
    }

    clearIPs(): void {
        this.ips.clear();
        this.failedIPs.clear();
    }

    clearSuccessfulIPs(): void {
        this.ips.clear();
    }

    private isValidIP(ip: string): boolean {
        return /^(\d{1,3}\.){3}\d{1,3}$/.test(ip) || /^([0-9a-fA-F:]+)$/.test(ip);
    }

    private async waitForRateLimit(): Promise<void> {
        const now = Date.now();
        const timeSinceLastRequest = now - this.lastRequestTime;
        
        if (timeSinceLastRequest > this.RATE_LIMIT_WINDOW) {
            this.requestCount = 0;
        }
        
        if (this.requestCount >= this.MAX_REQUESTS_PER_MINUTE) {
            const waitTime = this.RATE_LIMIT_WINDOW - timeSinceLastRequest;
            if (waitTime > 0) {
                await this.sleepWithCountdown(waitTime, this.requestCount, this.MAX_REQUESTS_PER_MINUTE);
                this.requestCount = 0;
                // Only show reset message once after countdown, not repeatedly
                if (this.debug) {
                    // Clear the countdown line and show completion
                    process.stdout.write('\r' + ' '.repeat(100) + '\r');
                }
            } else {
                this.requestCount = 0;
            }
        }
    }

    private sleep(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    private async sleepWithCountdown(totalMs: number, usedRequests: number, maxRequests: number): Promise<void> {
        return new Promise(resolve => {
            const startTime = Date.now();
            let lastDisplayedSeconds = -1;
            
            const updateCountdown = () => {
                const elapsed = Date.now() - startTime;
                const remaining = Math.max(0, totalMs - elapsed);
                const remainingSeconds = Math.ceil(remaining / 1000);
                
                if (remaining <= 0) {
                    clearInterval(interval);
                    // Show completion message only once at the very end
                    if (this.debug) {
                        process.stdout.write('\r' + ' '.repeat(100) + '\r');
                        this.debugComplete(`✅ Rate limit reset, continuing...`);
                    }
                    resolve();
                    return;
                }
                
                if (remainingSeconds !== lastDisplayedSeconds) {
                    lastDisplayedSeconds = remainingSeconds;
                    const totalSeconds = Math.ceil(totalMs / 1000);
                    const progressPercent = Math.round(((totalSeconds - remainingSeconds) / totalSeconds) * 100);
                    const progressBar = '█'.repeat(Math.floor(progressPercent / 5)) + '░'.repeat(20 - Math.floor(progressPercent / 5));
                    
                    this.debugUpdate(`⏳ Rate limit: ${remainingSeconds}s [${progressBar}] ${progressPercent}%`);
                }
            };
            
            updateCountdown();
            const interval = setInterval(updateCountdown, 200);
            
            setTimeout(() => {
                clearInterval(interval);
                // Show completion message only once when timeout completes
                if (this.debug) {
                    process.stdout.write('\r' + ' '.repeat(100) + '\r');
                    this.debugComplete(`✅ Rate limit reset, continuing...`);
                }
                resolve();
            }, totalMs);
        });
    }

    private async processIP(ip: string, timeout: number, maxRetries: number): Promise<{ ip: string; data?: LocationData; error?: string }> {
        let attempts = 0;
        
        while (attempts < maxRetries) {
            try {
                await this.waitForRateLimit();
                
                this.requestCount++;
                this.lastRequestTime = Date.now();
                
                const adjustedTimeout = timeout + (attempts * 2000);
                
                const timeoutPromise = new Promise<never>((_, reject) => {
                    setTimeout(() => reject(new Error('Request timeout')), adjustedTimeout);
                });
                
                const data = await Promise.race([
                    getLocationFromIP(ip), 
                    timeoutPromise
                ]) as LocationData;
                
                this.debugError(ip, '', true);
                this.ips.delete(ip);
                this.failedIPs.delete(ip);
                
                return { ip, data };
            } catch (error) {
                attempts++;
                const errorMsg = error instanceof Error ? error.message : 'Unknown error';
                
                this.debugError(ip, `${errorMsg} (${attempts}/${maxRetries})`);
                
                if (attempts >= maxRetries) {
                    this.failedIPs.add(ip);
                    return { ip, error: `${errorMsg} (${maxRetries} attempts)` };
                }
                
                await this.sleep(Math.min(1000 * Math.pow(2, attempts), 5000));
            }
        }
        
        this.failedIPs.add(ip);
        return { ip, error: 'Max retries exceeded' };
    }

    async bulkRequest(options: BulkRequestOptions = {}): Promise<BulkResult> {
        const {
            batchSize = 40,
            batchDelay = 65000,
            autoRetry = true,
            maxAutoRetries = 2,
            debug = false
        } = options;
        
        let requestTimeout = options.requestTimeout || 10000;
        let maxRetries = options.maxRetries || 2;

        this.debug = debug;

        if (this.isProcessing) {
            throw new Error('Bulk request already in progress');
        }

        this.isProcessing = true;
        const startTime = Date.now();
        const allIPs = this.getIPs();
        
        const result: BulkResult = {
            success: [],
            failed: [],
            stats: {
                total: allIPs.length,
                successful: 0,
                failed: 0,
                duration: 0,
                batchesProcessed: 0
            }
        };

        try {
            this.currentErrors.clear();
            let currentRetryRound = 0;
            
            while (currentRetryRound <= maxAutoRetries) {
                const currentIPs = this.getIPs();
                if (currentIPs.length === 0) break;
                
                if (currentRetryRound > 0 && debug) {
                    this.debugLog(`🔄 Auto-retry ${currentRetryRound}/${maxAutoRetries}: ${currentIPs.length} IPs`);
                }
                
                const batches: string[][] = [];
                for (let i = 0; i < currentIPs.length; i += batchSize) {
                    batches.push(currentIPs.slice(i, i + batchSize));
                }

                if (currentRetryRound === 0 && debug) {
                    this.debugLog(`🚀 Processing ${currentIPs.length} IPs in ${batches.length} batches`);
                }

                for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
                    const batch = batches[batchIndex];
                    const batchStartTime = Date.now();
                    
                    if (debug) {
                        this.debugUpdate(`📦 Batch ${batchIndex + 1}/${batches.length}...`);
                    }

                    const batchResults = await Promise.all(
                        batch.map(ip => this.processIP(ip, requestTimeout, maxRetries))
                    );

                    for (const batchResult of batchResults) {
                        if (batchResult.error) {
                            const existingFailed = result.failed.find(f => f.ip === batchResult.ip);
                            if (!existingFailed) {
                                result.failed.push({ 
                                    ip: batchResult.ip, 
                                    error: batchResult.error 
                                });
                            }
                        } else if (batchResult.data) {
                            result.failed = result.failed.filter(f => f.ip !== batchResult.ip);
                            
                            const existingSuccess = result.success.find(s => s.ip === batchResult.ip);
                            if (!existingSuccess) {
                                result.success.push({ 
                                    ip: batchResult.ip, 
                                    data: batchResult.data 
                                });
                            }
                        }
                    }

                    result.stats.batchesProcessed++;
                    const batchDuration = Date.now() - batchStartTime;
                    
                    if (debug) {
                        this.debugComplete(`✅ Batch ${batchIndex + 1}/${batches.length} (${batchDuration}ms)`);
                    }

                    if (this.debug && this.currentErrors.size > 0) {
                        this.debugUpdate('');
                    }

                    if (batchIndex < batches.length - 1) {
                        await this.sleep(batchDelay);
                    }
                }

                if (!autoRetry || this.failedIPs.size === 0) break;
                
                currentRetryRound++;
                
                if (currentRetryRound <= maxAutoRetries) {
                    requestTimeout = Math.min(requestTimeout * 1.5, 15000);
                    maxRetries = Math.min(maxRetries + 1, 4);
                    
                    const failedIPsArray = Array.from(this.failedIPs);
                    this.addIPs(failedIPsArray);
                    
                    await this.sleep(1000);
                }
            }

            this.currentErrors.clear();
            if (this.debug) {
                this.debugUpdate('');
            }

            result.stats.successful = result.success.length;
            result.stats.failed = result.failed.length;
            result.stats.duration = Date.now() - startTime;

            if (debug) {
                this.debugLog(`🎯 Completed: ${result.stats.successful}/${result.stats.total} (${result.stats.duration}ms)`);
            }

        } catch (error) {
            console.error('❌ Bulk request failed:', error);
            throw error;
        } finally {
            this.isProcessing = false;
            this.debug = false;
        }

        return result;
    }

    async retryFailedIPs(options: BulkRequestOptions = {}): Promise<BulkResult> {
        if (this.failedIPs.size === 0) {
            throw new Error('No failed IPs to retry');
        }

        const failedIPsArray = Array.from(this.failedIPs);
        this.addIPs(failedIPsArray);

        return this.bulkRequest(options);
    }

    getStats(): {
        totalIPs: number;
        failedIPs: number;
        isProcessing: boolean;
        lastRequestTime: Date | null;
        requestCount: number;
    } {
        return {
            totalIPs: this.ips.size,
            failedIPs: this.failedIPs.size,
            isProcessing: this.isProcessing,
            lastRequestTime: this.lastRequestTime ? new Date(this.lastRequestTime) : null,
            requestCount: this.requestCount
        };
    }
}
