import { DeviceInfo, LocationData, Metadata } from "@/types/index.type"
import { UAParser } from "./userAgentParser"


/**
 * User agent parser to extract device and browser information
 */
function parseUserAgent(userAgent: string): DeviceInfo {
    const parser = new UAParser(userAgent)
    const result = parser.getResult()

    return {
        browser: result.browser.name || null,
        browserVersion: result.browser.version || null,
        operatingSystem: result.os.name || null,
        osVersion: result.os.version || null,
        deviceType: result.device.type || 'desktop',
        deviceBrand: result.device.vendor || null,
        deviceModel: result.device.model || null,
        isMobile: result.extra.isMobile,
        isBot: result.extra.isBot
    }
}

/**
 * Extract IP address and version from request headers
 */
function getIpInfo(request: Request): { ip: string; ipVersion: string } {
    const forwarded = request.headers.get('x-forwarded-for')
    const realIp = request.headers.get('x-real-ip')
    const cfConnectingIp = request.headers.get('cf-connecting-ip') // Cloudflare

    // Ambil IP dari berbagai sources
    const url = new URL(request.url)
    const ip = forwarded?.split(',')[0]?.trim() ||
        realIp ||
        cfConnectingIp ||
        url.hostname ||
        'unknown'

    // Deteksi versi IP
    const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/
    const ipv6Regex = /^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/

    let ipVersion = 'unknown'
    if (ipv4Regex.test(ip)) {
        ipVersion = 'IPv4'
    } else if (ipv6Regex.test(ip)) {
        ipVersion = 'IPv6'
    }

    return { ip, ipVersion }
}

/**
 * Fetch ip location from external service (ip-api.com)
 * 
 * Free tier has rate limit 45 requests per minute
 * ---
 * For production use, consider using a paid service or self-hosted solution
 */
export async function getLocationFromIP(ip: string): Promise<LocationData | undefined> {
    try {
        const response = await fetch(`http://ip-api.com/json/${ip}`)
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`)
        }

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`)
        }

        const data = await response.json()

        if (data.status === 'success') {
            return {
                country: data.country,
                countryCode: data.countryCode,
                region: data.region,
                regionName: data.regionName,
                city: data.city,
                zip: data.zip,
                lat: data.lat,
                lon: data.lon,
                timezone: data.timezone,
                isp: data.isp,
                org: data.org,
            }
        }
    } catch (error) {
        throw error
    }
}

/**
 * Generate browser fingerprint sederhana
 */
function generateFingerprint(request: Request, device: DeviceInfo): string {
    const components = [
        device.browser,
        device.operatingSystem,
        request.headers.get('accept-language'),
        request.headers.get('accept-encoding'),
        device.deviceType
    ].filter(Boolean)

    return Buffer.from(components.join('|')).toString('base64')
}

/**
 * Generate atau mendapatkan session ID
 */
function getSessionId(request: Request): string {
    const cookieHeader = request.headers.get('cookie')
    if (cookieHeader) {
        const cookies = cookieHeader.split(';').reduce((acc, cookie) => {
            const [name, value] = cookie.trim().split('=')
            acc[name] = value
            return acc
        }, {} as Record<string, string>)

        const sessionCookie = cookies['session-id']
        if (sessionCookie) return sessionCookie
    }

    return `sess_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`
}

/**
 * Extract domain from referrer URL
 */
function getReferrerDomain(referrer?: string): string | undefined {
    if (!referrer) return undefined
    try {
        const url = new URL(referrer)
        return url.hostname
    } catch {
        return undefined
    }
}

/**
 * Collect analytics metadata from the request
 */
export async function collectAnalytics(request: Request | any): Promise<Metadata | undefined> {
    try {
        const userAgent = request.headers.get('user-agent') || ''
        const referrer = request.headers.get('referer') || undefined

        // Parse informasi dari request
        const { ip, ipVersion } = getIpInfo(request)
        const device = parseUserAgent(userAgent)
        const sessionId = getSessionId(request)
        const fingerprint = generateFingerprint(request, device)

        // Skip jika bot untuk menghemat resources
        if (device.isBot) {
            return
        }

        // User baru, ambil data lokasi dan simpan ke database
        const location = await getLocationFromIP(ip)
        const referrerDomain = getReferrerDomain(referrer)
        const url = new URL(request.url)

        const metadata: Metadata = {
            // IP and Location
            ip,
            ipVersion,
            country: location?.country,
            countryCode: location?.countryCode,
            region: location?.region,
            regionName: location?.regionName,
            city: location?.city,
            zip: location?.zip,
            latitude: location?.lat,
            longitude: location?.lon,
            timezone: location?.timezone,
            isp: location?.isp,
            organization: location?.org,

            // User Agent and Device
            userAgent,
            browser: device.browser,
            browserVersion: device.browserVersion,
            operatingSystem: device.operatingSystem,
            osVersion: device.osVersion,
            deviceType: device.deviceType,
            deviceBrand: device.deviceBrand,
            deviceModel: device.deviceModel,
            isMobile: device.isMobile,
            isBot: device.isBot,

            // Request Headers
            acceptLanguage: request.headers.get('accept-language'),
            acceptEncoding: request.headers.get('accept-encoding'),
            acceptCharset: request.headers.get('accept-charset'),
            cacheControl: request.headers.get('cache-control'),
            connection: request.headers.get('connection'),
            dnt: request.headers.get('dnt'),
            upgradeInsecure: request.headers.get('upgrade-insecure-requests'),

            // Referrer and Session
            referrer: referrer || null,
            referrerDomain: referrerDomain || null,
            sessionId,
            fingerprint,
            // Request Details
            requestMethod: request.method,
            requestUrl: request.url,
            requestPath: url.pathname,
            queryParams: JSON.stringify(Object.fromEntries(url.searchParams)),
            protocol: url.protocol,
            port: url.port ? parseInt(url.port) : null,

            createdAt: new Date(),
        }

        return metadata

    } catch (error) {
        throw new Error('Error collecting analytics data')
    }
}
